const sample = {
  "demo": true,
  "from": "sam@paperroute.example",
  "subject": "Survey",
  "body": "The refund never arrived and the experience was terrible.",
  "email": "sam@paperroute.example"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const haystack = String(item.body || item.body || item.subject || item.summary || '').toLowerCase();
const hits = [];
if (['terrible', 'refund', 'never', 'angry'].some((word) => haystack.includes(word))) {
  hits.push({ id: 'detractor', label: 'Detractor', weight: 3 });
}
if (['ok', 'fine'].some((word) => haystack.includes(word))) {
  hits.push({ id: 'passive', label: 'Passive', weight: 1 });
}
if (['love', 'great', 'thanks'].some((word) => haystack.includes(word))) {
  hits.push({ id: 'promoter', label: 'Promoter', weight: 2 });
}
hits.sort((a, b) => b.weight - a.weight);
const winner = hits[0] || { id: 'passive', label: 'passive', weight: 0 };
const draft = item.draft || ('Thanks for the note. We logged this as ' + winner.label + ' and will follow up shortly.');
const record = {
  label: winner.id,
  labelName: winner.label,
  confidence: hits.length ? Math.min(0.95, 0.45 + hits.length * 0.15) : 0.3,
  subject: item.subject || winner.label,
  body: draft,
  email: item.from || item.email || '',
  priority: winner.id,
  title: (item.subject || winner.label),
};
return {
  summary: 'Survey classified as ' + winner.label + ' (' + record.confidence.toFixed(2) + ').',
  route: winner.id,
  record,
  slackText: winner.label + ': ' + (item.subject || haystack.slice(0, 80)),
  actions: [{ app: 'mailbox', operation: 'label-and-draft', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'csat-detractor-followup',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
